/**
 * Guards prisma/install-baseline.json - the starting setup every NEW customer
 * install is seeded with (seed.ts, SEED_INSTALL_BASELINE=1). It is generated by
 * prisma/export-install-baseline.ts from an approved database and committed, so
 * nothing re-checks it at runtime. A permission or re-auth action removed from
 * the code later, or a credential slipping into a setting, must fail here
 * rather than on a customer's machine.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { PERMISSIONS, REAUTH_ACTIONS, SIDEBAR_ITEMS, FEATURE_PRIVILEGES } from '@digilog/shared';

const baseline = JSON.parse(
  readFileSync(join(__dirname, '..', '..', 'prisma', 'install-baseline.json'), 'utf8'),
) as {
  roles: Array<{ name: string; permissions: string[] }>;
  roleConfigs: Array<{ role: string; sidebarItems: string[]; permissions: Record<string, boolean> }>;
  settings: Array<{ configKey: string; configValue: any }>;
};
const setting = (key: string) => baseline.settings.find((s) => s.configKey === key)?.configValue;

describe('install baseline (fresh-install starting setup)', () => {
  it('has the roles the OQ scripts are written against', () => {
    const names = baseline.roles.map((r) => r.name).sort();
    expect(names).toEqual(['ADMIN', 'MANAGER', 'OPERATOR', 'QA', 'SHIFTOFFICER', 'SUPERVISOR', 'SUPER_ADMIN']);
  });

  // 2026-10-21 (operator): "viewer role should not be there in the application".
  // MAINTENANCE was in the same state. Neither may come back - not as a role, and
  // not as a leftover key or list entry in any setting (tablet-access,
  // export-options, qnn-notifications and dashboard-cards all carried one).
  it('mentions no VIEWER or MAINTENANCE role anywhere (roles, configs, settings, code defaults)', () => {
    const roleKey = /"(VIEWER|MAINTENANCE)"/;
    expect(JSON.stringify(baseline)).not.toMatch(roleKey);
    const defaults = readFileSync(join(__dirname, '..', '..', 'prisma', 'default-roles.ts'), 'utf8');
    expect(defaults).not.toMatch(/name: '(VIEWER|MAINTENANCE)'/);
  });

  it('grants only permissions that exist in the code', () => {
    const valid = new Set<string>(Object.values(PERMISSIONS));
    const unknown = baseline.roles.flatMap((r) => r.permissions.filter((p) => !valid.has(p)).map((p) => `${r.name}:${p}`));
    expect(unknown).toEqual([]);
  });

  it('keeps ADMIN an administration role, not an operations role', () => {
    const admin = baseline.roles.find((r) => r.name === 'ADMIN')!;
    expect(admin.permissions.some((p) => p.startsWith('FILTER_') || p.startsWith('PM_'))).toBe(false);
  });

  it('role configs reference only live sidebar items and feature privileges', () => {
    const sidebar = new Set(SIDEBAR_ITEMS.map((s) => s.id));
    const privileges = new Set(FEATURE_PRIVILEGES.map((p) => p.id));
    for (const rc of baseline.roleConfigs) {
      expect(rc.sidebarItems.filter((s) => !sidebar.has(s)), rc.role).toEqual([]);
      expect(Object.keys(rc.permissions).filter((id) => !privileges.has(id)), rc.role).toEqual([]);
    }
  });

  it('turns e-signature on for real actions only', () => {
    const reauth = setting('action-reauth') as Record<string, string[]>;
    expect(Object.keys(reauth).length).toBeGreaterThan(0);
    expect(Object.keys(reauth).filter((a) => !(a in REAUTH_ACTIONS))).toEqual([]);
  });

  it('refuses tablet login to the web-only roles (QA, ADMIN, MANAGER)', () => {
    // Mirrors lib/tablet-access.ts: once any role is configured, a role is allowed
    // only if its own entry lists 'login'.
    const tablet = setting('tablet-access') as Record<string, string[]>;
    expect(Object.keys(tablet).length).toBeGreaterThan(0);
    for (const role of ['QA', 'ADMIN', 'MANAGER']) {
      expect((tablet[role] ?? []).includes('login'), role).toBe(false);
    }
    for (const role of ['OPERATOR', 'SUPERVISOR', 'SHIFTOFFICER']) {
      expect(tablet[role]?.includes('login'), role).toBe(true);
    }
  });

  it('ships no credentials, site addresses or site-specific references', () => {
    const keys = baseline.settings.map((s) => s.configKey);
    for (const forbidden of ['notification-email', 'notification-sms', 'backup', 'cleaning-profile-assignment', 'ldap']) {
      expect(keys).not.toContain(forbidden);
    }
    const text = JSON.stringify(baseline);
    expect(text).not.toMatch(/192\.168\.|10\.\d+\.\d+\.\d+|digilog123/);
    expect(text).not.toMatch(/"(password|secret|token|apiKey|smtpPass(word)?)"\s*:\s*"[^"]+"/i);
  });

  it('carries none of the source PC test leftovers', () => {
    const reasons = (setting('filter-cleaning-reasons')?.value ?? []).map((r: any) => r.key);
    expect(reasons).not.toContain('TEST');
    expect(reasons).not.toContain('XXXX');
    expect(JSON.stringify(setting('filter-field-options'))).not.toMatch(/xdghg|"Test"/);
    expect(setting('report-page-titles')?.performedByLabel ?? '').not.toMatch(/\(\d{6,}\)/);
  });
});
